  // This is not safe; requires that user has specified correct adapter class for @JsonAdapter
  mapped =
      jsonAdapterFactory.getTypeAdapter(
          constructorConstructor, context, fieldType, annotation, false);
}
boolean jsonAdapterPresent = mapped != null;
if (mapped == null) {
  mapped = context.getAdapter(fieldType);
}

@SuppressWarnings("unchecked")
TypeAdapter<Object> typeAdapter = (TypeAdapter<Object>) mapped;
TypeAdapter<Object> writeTypeAdapter;
if (serialize) {
  writeTypeAdapter =
      jsonAdapterPresent
          ? typeAdapter
          : new TypeAdapterRuntimeTypeWrapper<>(context, typeAdapter, fieldType.getType());
} else {
  // Will never actually be used, but we set it to avoid confusing nullness-analysis tools
  writeTypeAdapter = typeAdapter;

if (isDifferentType) {
  @SuppressWarnings("unchecked")
  TypeAdapter<T> runtimeTypeAdapter =
      (TypeAdapter<T>) context.getAdapter(TypeToken.get(runtimeType));
  // For backward compatibility only check ReflectiveTypeAdapterFactory.Adapter here but not any
  // other wrapping adapters, see
  // https://github.com/google/gson/pull/1787#issuecomment-1222175189
  if (!(runtimeTypeAdapter instanceof ReflectiveTypeAdapterFactory.Adapter)) {
    // The user registered a type adapter for the runtime type, so we will use that
    chosen = runtimeTypeAdapter;
  } else if (!isReflective(delegate)) {
    // The user registered a type adapter for Base class, so we prefer it over the
    // reflective type adapter for the runtime type
    chosen = delegate;
  } else {
    // Use the type adapter for runtime type
    chosen = runtimeTypeAdapter;
  }
}
chosen.write(out, value);

@Override
public T read(JsonReader in) throws IOException {
  return delegate.read(in);
}

/// Returns a pointer to the output buffer content. No terminating null
/// character is appended.
FMT_CONSTEXPR20 auto data() const -> const char* { return str_; }

/// Returns a pointer to the output buffer content with terminating null
/// character appended.
FMT_CONSTEXPR20 auto c_str() const -> const char* {
  buffer_[buffer_size - 1] = '\0';
  return str_;
}

/// Returns the number of characters written to the output buffer.
FMT_CONSTEXPR20 auto size() const -> size_t {
  return detail::to_unsigned(buffer_ - str_ + buffer_size - 1);
}

static FMT_CONSTEXPR20 void grow(detail::buffer<T>& buf, size_t size) {
  detail::abort_fuzzing_if(size > 5000);
  auto& self = static_cast<basic_memory_buffer&>(buf);
  const size_t max_size =
      std::allocator_traits<Allocator>::max_size(self.alloc_);
  size_t old_capacity = buf.capacity();
  size_t new_capacity = old_capacity + old_capacity / 2;
  if (size > new_capacity)
    new_capacity = size;
  else if (new_capacity > max_size)
    new_capacity = max_of(size, max_size);

T* old_data = buf.data();
T* new_data = self.alloc_.allocate(new_capacity);
// Suppress a bogus -Wstringop-overflow in gcc 13.1 (#3481).
detail::assume(buf.size() <= new_capacity);
// The following code doesn't throw, so the raw pointer above doesn't leak.
memcpy(new_data, old_data, buf.size() * sizeof(T));
self.set(new_data, new_capacity);
// deallocate must not throw according to the standard, but even if it does,
// the buffer already uses the new storage and will deallocate it in
// destructor.
if (old_data != self.store_) self.alloc_.deallocate(old_data, old_capacity);

/// Reports an error if using the manual argument indexing; otherwise returns
/// the next argument index and switches to the automatic indexing.
FMT_CONSTEXPR auto next_arg_id() -> int {
  if (next_arg_id_ < 0) {
    report_error("cannot switch from manual to automatic argument indexing");
    return 0;
  }
  int id = next_arg_id_++;
  do_check_arg_id(id);
  return id;

/// Reports an error if using the automatic argument indexing; otherwise
/// switches to the manual indexing.
FMT_CONSTEXPR void check_arg_id(int id) {
  if (next_arg_id_ > 0) {
    report_error("cannot switch from automatic to manual argument indexing");
    return;
  }
  next_arg_id_ = -1;
  do_check_arg_id(id);
}

template <typename OutputIt, typename S, typename... T,
          FMT_ENABLE_IF(is_compiled_string<S>::value)>
auto format_to_n(OutputIt out, size_t n, const S& fmt, T&&... args)
    -> format_to_n_result<OutputIt> {
  using traits = detail::fixed_buffer_traits;
  auto buf = detail::iterator_buffer<OutputIt, char, traits>(out, n);
  fmt::format_to(appender(buf), fmt, std::forward<T>(args)...);
  return {buf.out(), buf.count()};
}

class fixed_buffer_traits {
 private:
  size_t count_ = 0;
  size_t limit_;

 public:
  constexpr explicit fixed_buffer_traits(size_t limit) : limit_(limit) {}
  constexpr auto count() const -> size_t { return count_; }
  FMT_CONSTEXPR auto limit(size_t size) -> size_t {
    size_t n = limit_ > count_ ? limit_ - count_ : 0;
    count_ += size;
    return min_of(size, n);
  }
};

  using traits = detail::fixed_buffer_traits;
  auto buf = detail::iterator_buffer<OutputIt, char, traits>(out, n);
  fmt::format_to(appender(buf), fmt, std::forward<T>(args)...);
  return {buf.out(), buf.count()};
}

auto out() -> OutputIt {
  flush();
  return out_;
}
auto count() const -> size_t { return Traits::count() + this->size(); }

void ostream::grow(buffer<char>& buf, size_t) {
  if (buf.size() == buf.capacity()) static_cast<ostream&>(buf).flush();
}

inline void flush() {
  if (size() == 0) return;
  file_.write(data(), size() * sizeof(data()[0]));
  clear();
}

auto file::write(const void* buffer, size_t count) -> size_t {
  rwresult result = 0;
  FMT_RETRY(result, FMT_POSIX_CALL(write(fd_, buffer, convert_rwcount(count))));
  if (result < 0)
    FMT_THROW(system_error(errno, FMT_STRING("cannot write to file")));
  return detail::to_unsigned(result);
}
